        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('90040010-0000-4000-8000-000000000001', 'Based on the reading passage, answer: (i) What metaphor does the author use to describe the water-regulating function of forests? (ii) Explain how deforestation accelerates river siltation and flooding. (iii) Find a word from the passage that means ''arid or lacking sufficient moisture''.', NULL, NULL, 'CASE', 'English', 'Reading Comprehension', 10, '(i) The author uses the metaphor of ''giant green sponges'' to illustrate how forests absorb, store, and gradually release rainwater. (ii) When tree cover is destroyed, heavy rainfall strikes unprotected topsoil directly, dislodging dirt and carrying sediment down into riverbeds, which reduces water-carrying capacity and causes flooding. (iii) The word is ''arid''.', '1 Mark for metaphor identification; 2 Marks for deforestation siltation mechanism; 1 Mark for vocabulary synonym', 'Ecosystems across our planet depend on delicate ecological balances. Forests act as giant green sponges, soaking up rainwater during wet spells, replenishing underground aquifers, and gradually releasing water throughout arid dry seasons. When hillsides are denuded through deforestation, torrential downpours wash away fertile topsoil into river channels, silting reservoirs and causing destructive flash floods in lower plains. Preserving indigenous old-growth biodiversity is not merely an aesthetic choice, but an ecological necessity for sustainable human survival.', NULL, 'MEDIUM', true),
        ('90040010-0000-4000-8000-000000000002', 'Fill in the blank with the correct determiner: ''There wasn''t _______ milk left in the refrigerator, so we couldn''t make tea.''', '{"A":"much","B":"many","C":"few","D":"several"}'::jsonb, 'A', 'MCQ', 'English', 'Determiners', 2, NULL, NULL, NULL, '''Milk'' is an uncountable noun, so the quantifier ''much'' is grammatically appropriate with the negative verb.', 'MEDIUM', true),
        ('90040010-0000-4000-8000-000000000003', 'Choose the correct modal to complete the sentence: ''You _______ submit your project dossier before 5:00 PM today, as late submissions are rejected.''', '{"A":"must","B":"might","C":"could","D":"would"}'::jsonb, 'A', 'MCQ', 'English', 'Modals', 2, NULL, NULL, NULL, '''Must'' expresses strong obligation and strict official necessity.', 'MEDIUM', true),
        ('90040010-0000-4000-8000-000000000004', 'Subject-Verb Concord: ''Neither the principal nor the teachers _______ present at the venue when the storm hit.''', '{"A":"was","B":"were","C":"is","D":"are"}'::jsonb, 'B', 'MCQ', 'English', 'Subject-Verb Concord', 2, NULL, NULL, NULL, 'With correlative conjunctions ''neither...nor'', the verb agrees with the nearer subject (''teachers'', which is plural).', 'MEDIUM', true),
        ('90040010-0000-4000-8000-000000000005', 'You recently visited an old age home with your school voluntary service club. Write a Descriptive Paragraph in about 100-120 words describing your observations, the residents'' emotions, and the impact the visit left on your mind.', NULL, NULL, 'LA', 'English', 'Descriptive Paragraph', 4, 'A Visit to the Old Age Home: Last Saturday, our school voluntary club visited ''Sandhya Aashray'', a serene refuge for senior citizens. Walking into the sunny courtyard, we were greeted by silver-haired elders whose eyes reflected both wisdom and an unspoken yearning for companionship. We spent the afternoon singing melodious vintage songs, reciting poetry, and listening to their poignant life journeys. Mrs. Shanti, an eighty-year-old retired teacher, affectionately held my hand while reminiscing about her teaching days. Despite physical frailties, their grace and warm smiles were deeply touching. However, a lingering melancholy pervaded the corridors, revealing the quiet sting of abandonment by their busy families. The experience awakened in me a profound sense of gratitude and reaffirmed that our elders deserve dignity, unconditional love, and constant care.', '2 Marks for content relevance and vivid sensory descriptions; 2 Marks for organization and vocabulary; 1 Mark for grammatical accuracy', NULL, NULL, 'MEDIUM', true),
        ('90040010-0000-4000-8000-000000000006', 'Reference to Context (Poetry - The Road Not Taken): ''Two roads diverged in a yellow wood, / And sorry I could not travel both / And be one traveler, long I stood / And looked down one as far as I could...'' (i) What do the ''two diverging roads'' symbolize in human life? (ii) Why did the poet choose the second road? (iii) What does the phrase ''yellow wood'' signify?', NULL, NULL, 'LA', 'English', 'The Road Not Taken', 10, '(i) The two diverging roads symbolize the inevitable, fateful choices and decisions that every individual must make in the journey of life. (ii) The poet chose the second road because it was grassy, less traveled by the crowd, and ''wanted wear'', representing an unconventional, bold path. (iii) ''Yellow wood'' signifies the autumn season, representing maturity, change, and the passage of time.', '1.5 Marks for symbolical interpretation of roads; 2 Marks for justifying road choice; 1.5 Marks for autumn season significance', NULL, NULL, 'MEDIUM', true),
        ('90040010-0000-4000-8000-000000000007', 'Short Answer (Beehive): How did Evelyn Glennie achieve her monumental musical success despite losing her hearing ability at a young age? What inspiration does she offer to differently-abled people?', NULL, NULL, 'LA', 'English', 'The Sound of Music', 10, 'Evelyn Glennie refused to surrender to profound deafness. Guided by percussionist Ron Forbes, she learned to sense acoustic vibrations through different parts of her body rather than her ears—feeling higher drums from the waist up and lower drums from the waist down. Through iron willpower and unremitting practice, she mastered over a thousand percussion instruments and became a celebrated international soloist, proving that physical impairments cannot constrain determination.', '1.5 Marks for Ron Forbes guidance and vibration sensing technique; 1.5 Marks for inspirational message of perseverance', NULL, NULL, 'MEDIUM', true)
