        ('90040016-0000-4000-8000-000000000004', 'Subject-Verb Concord: ''Neither the principal nor the teachers _______ present at the venue when the storm hit.''', '{"A":"was","B":"were","C":"is","D":"are"}'::jsonb, 'B', 'MCQ', 'English', 'Subject-Verb Concord', 2, NULL, NULL, NULL, 'With correlative conjunctions ''neither...nor'', the verb agrees with the nearer subject (''teachers'', which is plural).', 'MEDIUM', true),
        ('90040016-0000-4000-8000-000000000005', 'You recently visited an old age home with your school voluntary service club. Write a Descriptive Paragraph in about 100-120 words describing your observations, the residents'' emotions, and the impact the visit left on your mind.', NULL, NULL, 'LA', 'English', 'Descriptive Paragraph', 4, 'A Visit to the Old Age Home: Last Saturday, our school voluntary club visited ''Sandhya Aashray'', a serene refuge for senior citizens. Walking into the sunny courtyard, we were greeted by silver-haired elders whose eyes reflected both wisdom and an unspoken yearning for companionship. We spent the afternoon singing melodious vintage songs, reciting poetry, and listening to their poignant life journeys. Mrs. Shanti, an eighty-year-old retired teacher, affectionately held my hand while reminiscing about her teaching days. Despite physical frailties, their grace and warm smiles were deeply touching. However, a lingering melancholy pervaded the corridors, revealing the quiet sting of abandonment by their busy families. The experience awakened in me a profound sense of gratitude and reaffirmed that our elders deserve dignity, unconditional love, and constant care.', '2 Marks for content relevance and vivid sensory descriptions; 2 Marks for organization and vocabulary; 1 Mark for grammatical accuracy', NULL, NULL, 'MEDIUM', true),
        ('90040016-0000-4000-8000-000000000006', 'Short Answer (Beehive): How did Evelyn Glennie achieve her monumental musical success despite losing her hearing ability at a young age? What inspiration does she offer to differently-abled people?', NULL, NULL, 'LA', 'English', 'The Sound of Music', 10, 'Evelyn Glennie refused to surrender to profound deafness. Guided by percussionist Ron Forbes, she learned to sense acoustic vibrations through different parts of her body rather than her ears—feeling higher drums from the waist up and lower drums from the waist down. Through iron willpower and unremitting practice, she mastered over a thousand percussion instruments and became a celebrated international soloist, proving that physical impairments cannot constrain determination.', '1.5 Marks for Ron Forbes guidance and vibration sensing technique; 1.5 Marks for inspirational message of perseverance', NULL, NULL, 'MEDIUM', true),
        ('90040016-0000-4000-8000-000000000007', 'Short Answer (Moments): In ''The Lost Child'', describe the transformation in the little child''s desires before and after he got separated from his parents at the spring fair.', NULL, NULL, 'LA', 'English', 'The Lost Child', 10, 'Before getting lost, the child was dazzled by the vibrant fair, longing for toys, dragonflies, burfi sweets, colorful balloons, and a ride on the roundabout. However, the moment he realized he was separated, overwhelming panic gripped him. All worldly attractions lost their allure completely; he sobbed uncontrollably, rejecting all gifts and crying only for his father and mother, showing that parental presence transcends all material desires.', '1.5 Marks for contrasting material longing with separation panic; 1.5 Marks for parent supremacy conclusion', NULL, NULL, 'MEDIUM', true)
        INSERT INTO learn_test_questions (id, mock_test_id, question_id, section_name, marks, order_index, question_sub_num)
        VALUES
