        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('90040017-0000-4000-8000-000000000001', 'Refer to the text and answer: (i) How do adaptive learning platforms cater to individual learners according to the passage? (ii) What crucial pedagogical dimensions remain outside the capability of artificial algorithms? (iii) Give the antonym of ''uniform'' as used in the context.', NULL, NULL, 'CASE', 'English', 'Reading Comprehension', 10, '(i) Adaptive platforms use diagnostic algorithms to measure response times, pinpoint misconceptions, and customize instructional scaffolding to each student''s pace. (ii) Human emotional intelligence, peer empathy, moral values, and nuanced creative debates cannot be automated. (iii) Antonym: ''Divergent'', ''varied'', or ''customized''.', '1.5 Marks for adaptive system capabilities; 1.5 Marks for human affective aspects; 1 Mark for contextual antonym', 'Artificial Intelligence and digital computing have reshaped the learning landscape. Traditional classrooms relied heavily on uniform teacher-led pacing, often leaving divergent learners struggling or bored. Adaptive learning platforms utilize diagnostic algorithms to measure student response times, identify cognitive misconceptions, and tailor instructional scaffolding to individual needs. However, educational psychologists emphasize that emotional intelligence, peer empathy, moral compass, and creative debate cannot be replicated by silicon processors.', NULL, 'MEDIUM', true),
        ('90040017-0000-4000-8000-000000000002', 'Fill in the blank with the correct determiner: ''There wasn''t _______ milk left in the refrigerator, so we couldn''t make tea.''', '{"A":"much","B":"many","C":"few","D":"several"}'::jsonb, 'A', 'MCQ', 'English', 'Determiners', 2, NULL, NULL, NULL, '''Milk'' is an uncountable noun, so the quantifier ''much'' is grammatically appropriate with the negative verb.', 'MEDIUM', true),
        ('90040017-0000-4000-8000-000000000003', 'Choose the correct modal to complete the sentence: ''You _______ submit your project dossier before 5:00 PM today, as late submissions are rejected.''', '{"A":"must","B":"might","C":"could","D":"would"}'::jsonb, 'A', 'MCQ', 'English', 'Modals', 2, NULL, NULL, NULL, '''Must'' expresses strong obligation and strict official necessity.', 'MEDIUM', true),
        ('90040017-0000-4000-8000-000000000004', 'Subject-Verb Concord: ''Neither the principal nor the teachers _______ present at the venue when the storm hit.''', '{"A":"was","B":"were","C":"is","D":"are"}'::jsonb, 'B', 'MCQ', 'English', 'Subject-Verb Concord', 2, NULL, NULL, NULL, 'With correlative conjunctions ''neither...nor'', the verb agrees with the nearer subject (''teachers'', which is plural).', 'MEDIUM', true),
        ('90040017-0000-4000-8000-000000000005', 'Taking inspiration from the theme of empathy and resilience, write a Diary Entry in about 100-120 words expressing your feelings when you helped a stray injured puppy recover and found it a loving home.', NULL, NULL, 'LA', 'English', 'Diary Entry', 4, 'Dear Diary,
        INSERT INTO learn_test_questions (id, mock_test_id, question_id, section_name, marks, order_index, question_sub_num)
        VALUES
