        ('9004001b-0001-4000-8000-000000000001', '90040000-0000-4000-8000-00000000001b', '9004001b-0000-4000-8000-000000000001', 'Section A: Grammar & Concept', 3, 1, '1'),
        ('9004001b-0001-4000-8000-000000000002', '90040000-0000-4000-8000-00000000001b', '9004001b-0000-4000-8000-000000000002', 'Section A: Grammar & Concept', 3, 2, '2'),
