        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('9004001c-0000-4000-8000-000000000001', 'Fill in the blank with the correct determiner: ''There wasn''t _______ milk left in the refrigerator, so we couldn''t make tea.''', '{"A":"much","B":"many","C":"few","D":"several"}'::jsonb, 'A', 'MCQ', 'English', 'Determiners', 3, NULL, NULL, NULL, '''Milk'' is an uncountable noun, so the quantifier ''much'' is grammatically appropriate with the negative verb.', 'MEDIUM', true),
        ('9004001c-0000-4000-8000-000000000002', 'Choose the correct modal to complete the sentence: ''You _______ submit your project dossier before 5:00 PM today, as late submissions are rejected.''', '{"A":"must","B":"might","C":"could","D":"would"}'::jsonb, 'A', 'MCQ', 'English', 'Modals', 3, NULL, NULL, NULL, '''Must'' expresses strong obligation and strict official necessity.', 'MEDIUM', true),
        ('9004001c-0000-4000-8000-000000000003', 'Subject-Verb Concord: ''Neither the principal nor the teachers _______ present at the venue when the storm hit.''', '{"A":"was","B":"were","C":"is","D":"are"}'::jsonb, 'B', 'MCQ', 'English', 'Subject-Verb Concord', 3, NULL, NULL, NULL, 'With correlative conjunctions ''neither...nor'', the verb agrees with the nearer subject (''teachers'', which is plural).', 'MEDIUM', true),
        ('9004001c-0000-4000-8000-000000000004', 'Short Answer (Moments): In ''The Lost Child'', describe the transformation in the little child''s desires before and after he got separated from his parents at the spring fair.', NULL, NULL, 'SA', 'English', 'The Lost Child', 6, 'Before getting lost, the child was dazzled by the vibrant fair, longing for toys, dragonflies, burfi sweets, colorful balloons, and a ride on the roundabout. However, the moment he realized he was separated, overwhelming panic gripped him. All worldly attractions lost their allure completely; he sobbed uncontrollably, rejecting all gifts and crying only for his father and mother, showing that parental presence transcends all material desires.', '1.5 Marks for contrasting material longing with separation panic; 1.5 Marks for parent supremacy conclusion', NULL, NULL, 'MEDIUM', true),
        ('9004001c-0000-4000-8000-000000000005', 'Long Answer (Beehive / Moments): In ''The Last Leaf'', Behrman sacrificed his life to save young Johnsy. Elucidate how Behrman''s masterpiece was not a painting on a gallery canvas, but an act of supreme selfless love that rekindled the will to live.', NULL, NULL, 'LA', 'English', 'The Last Leaf', 10, 'In O. Henry''s ''The Last Leaf'', young artist Johnsy fell severely ill with pneumonia and became psychologically convinced that she would die when the last ivy leaf fell from the brick wall outside her window. Old Behrman, a sixty-year-old struggling artist whose lifelong dream was to paint a masterpiece, learned of her despair. On a freezing, stormy night with torrential rain and sleet, Behrman climbed a ladder with a lantern and painted a single, lifelike ivy leaf on the wall after the real leaf fell. Seeing the leaf withstand the howling tempest, Johnsy realized the sin of wishing to die, and her will to live was restored. Behrman contracted pneumonia from the freezing rain and died shortly after. His leaf was a true masterpiece—not of commercial art, but of supreme self-sacrifice and compassion that saved a dying human life.', '2 Marks for Johnsy''s psychological despair; 2 Marks for Behrman''s nocturnal painting in storm; 2 Marks for evaluating the masterpiece as supreme human sacrifice', NULL, NULL, 'MEDIUM', true)
        INSERT INTO learn_test_questions (id, mock_test_id, question_id, section_name, marks, order_index, question_sub_num)
