        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('9004002e-0000-4000-8000-000000000001', 'Based on the reading passage, answer: (i) What metaphor does the author use to describe the water-regulating function of forests? (ii) Explain how deforestation accelerates river siltation and flooding. (iii) Find a word from the passage that means ''arid or lacking sufficient moisture''.', NULL, NULL, 'CASE', 'English', 'Reading Comprehension', 10, '(i) The author uses the metaphor of ''giant green sponges'' to illustrate how forests absorb, store, and gradually release rainwater. (ii) When tree cover is destroyed, heavy rainfall strikes unprotected topsoil directly, dislodging dirt and carrying sediment down into riverbeds, which reduces water-carrying capacity and causes flooding. (iii) The word is ''arid''.', '1 Mark for metaphor identification; 2 Marks for deforestation siltation mechanism; 1 Mark for vocabulary synonym', 'Ecosystems across our planet depend on delicate ecological balances. Forests act as giant green sponges, soaking up rainwater during wet spells, replenishing underground aquifers, and gradually releasing water throughout arid dry seasons. When hillsides are denuded through deforestation, torrential downpours wash away fertile topsoil into river channels, silting reservoirs and causing destructive flash floods in lower plains. Preserving indigenous old-growth biodiversity is not merely an aesthetic choice, but an ecological necessity for sustainable human survival.', NULL, 'MEDIUM', true),
        ('9004002e-0000-4000-8000-000000000002', 'Refer to the text and answer: (i) How do adaptive learning platforms cater to individual learners according to the passage? (ii) What crucial pedagogical dimensions remain outside the capability of artificial algorithms? (iii) Give the antonym of ''uniform'' as used in the context.', NULL, NULL, 'CASE', 'English', 'Reading Comprehension', 10, '(i) Adaptive platforms use diagnostic algorithms to measure response times, pinpoint misconceptions, and customize instructional scaffolding to each student''s pace. (ii) Human emotional intelligence, peer empathy, moral values, and nuanced creative debates cannot be automated. (iii) Antonym: ''Divergent'', ''varied'', or ''customized''.', '1.5 Marks for adaptive system capabilities; 1.5 Marks for human affective aspects; 1 Mark for contextual antonym', 'Artificial Intelligence and digital computing have reshaped the learning landscape. Traditional classrooms relied heavily on uniform teacher-led pacing, often leaving divergent learners struggling or bored. Adaptive learning platforms utilize diagnostic algorithms to measure student response times, identify cognitive misconceptions, and tailor instructional scaffolding to individual needs. However, educational psychologists emphasize that emotional intelligence, peer empathy, moral compass, and creative debate cannot be replicated by silicon processors.', NULL, 'MEDIUM', true)
        INSERT INTO learn_test_questions (id, mock_test_id, question_id, section_name, marks, order_index, question_sub_num)
        VALUES
